#pragma once
#include <utility>
#include "Common.h"
#include <string>
#include <iostream>
enum Type {
    R, I, S, B, U, J
};
struct InstructionBase {
    unsigned opcode;
    unsigned rs1;
    unsigned rs2;
    unsigned rd;
    unsigned funct3;
    unsigned funct7;
    int imm;
    unsigned inst;
    Type t;
    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(0), t(R) {}
    explicit InstructionBase(unsigned i) : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(i == 0 ? -1 : 0), t(R) {
        if (i != 0) throw std::invalid_argument("Only NOP instruction allowed via this constructor");
    }
    static constexpr unsigned int bin_mask(int digits) { return (digits < 32) ? ((1u << digits) - 1) : ~0u; }
    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        if (hi >= 32 || lo < 0 || hi <= lo) throw std::invalid_argument("Invalid digit range");
        return (n >> lo) & bin_mask(hi - lo + 1);
    }
    static unsigned int expand_digit(unsigned int digit, int lo) {
        if (lo < 0 || lo >= 32) throw std::invalid_argument("Invalid expansion position");
        return digit << lo;
    }
    bool is_valid(const std::string &key) const {
        if (key == "opcode" || key == "inst" || key == "t") return true;
        switch (t) {
            case R: return key == "rs1" || key == "rs2" || key == "rd" || key == "funct3" || key == "funct7";
            case I: return key == "rs1" || key == "rd" || key == "funct3" || key == "imm";
            case S: return key == "rs1" || key == "rs2" || key == "funct3" || key == "imm";
            case B: return key == "rs1" || key == "rs2" || key == "funct3" || key == "imm";
            case U: return key == "rd" || key == "imm";
            case J: return key == "rd" || key == "imm";
        }
        return false;
    }
    void verify(const std::string &key) const {
        if (!is_valid(key)) throw InvalidAccess("Invalid field access for instruction type");
    }
    void debug() const {
        std::cout << "Inst: 0x" << std::hex << inst << " (Type: " << static_cast<int>(t) << ")\n";
        if (is_valid("opcode")) std::cout << "  opcode: " << opcode << "\n";
        if (is_valid("rs1")) std::cout << "  rs1: " << rs1 << "\n";
        if (is_valid("rs2")) std::cout << "  rs2: " << rs2 << "\n";
        if (is_valid("rd")) std::cout << "  rd: " << rd << "\n";
        if (is_valid("funct3")) std::cout << "  funct3: " << funct3 << "\n";
        if (is_valid("funct7")) std::cout << "  funct7: " << funct7 << "\n";
        if (is_valid("imm")) std::cout << "  imm: " << imm << "\n";
    }
    bool has_op1() const { return is_valid("rs1"); }
    bool has_op2() const { return is_valid("rs2"); }
};
struct InstructionR : public InstructionBase {
    InstructionR(unsigned i) {
        inst = i;
        t = R;
        opcode = get_digits(i, 6, 0);
        rd = get_digits(i, 11, 7);
        funct3 = get_digits(i, 14, 12);
        rs1 = get_digits(i, 19, 15);
        rs2 = get_digits(i, 24, 20);
        funct7 = get_digits(i, 31, 25);
    }
};
struct InstructionI : public InstructionBase {
    InstructionI(unsigned i) {
        inst = i;
        t = I;
        opcode = get_digits(i, 6, 0);
        rd = get_digits(i, 11, 7);
        funct3 = get_digits(i, 14, 12);
        rs1 = get_digits(i, 19, 15);
        int imm_lo = static_cast<int>(get_digits(i, 31, 20));
        imm = (imm_lo << 12) >> 12; // Sign extend
    }
};
struct InstructionS : public InstructionBase {
    InstructionS(unsigned i) {
        inst = i;
        t = S;
        opcode = get_digits(i, 6, 0);
        funct3 = get_digits(i, 14, 12);
        rs1 = get_digits(i, 19, 15);
        rs2 = get_digits(i, 24, 20);
        int imm_hi = static_cast<int>(get_digits(i, 31, 25));
        int imm_lo = get_digits(i, 11, 7);
        imm = ((imm_hi << 5) | imm_lo) << 20 >> 20; // Sign extend
    }
};
struct InstructionB : public InstructionBase {
    InstructionB(unsigned i) {
        inst = i;
        t = B;
        opcode = get_digits(i, 6, 0);
        funct3 = get_digits(i, 14, 12);
        rs1 = get_digits(i, 19, 15);
        rs2 = get_digits(i, 24, 20);
        int imm_hi = static_cast<int>(get_digits(i, 31, 25));
        int imm_mid = get_digits(i, 7, 7);
        int imm_lo = get_digits(i, 30, 25);
        imm = ((imm_hi << 1) | (imm_mid << 11) | (imm_lo << 12)) >> 19; // Sign extend
    }
};
struct InstructionU : public InstructionBase {
    InstructionU(unsigned i) {
        inst = i;
        t = U;
        opcode = get_digits(i, 6, 0);
        rd = get_digits(i, 11, 7);
        int imm_hi = static_cast<int>(get_digits(i, 31, 12));
        imm = imm_hi << 12; // Sign extend
    }
};
struct InstructionJ : public InstructionBase {
    InstructionJ(unsigned i) {
        inst = i;
        t = J;
        opcode = get_digits(i, 6, 0);
        rd = get_digits(i, 19, 15);
        int imm_hi = static_cast<int>(get_digits(i, 31, 20));
        int imm_mid = get_digits(i, 19, 12);
        int imm_lo = get_digits(i, 20, 20);
        imm = ((imm_hi << 1) | (imm_mid << 11) | (imm_lo << 20)) >> 10; // Sign extend
    }
};
